import { useState } from "react";
import { useApp } from "../../context/AppContext";
import { EmptyState } from "../../components/UI";

export function IlanVerSayfasi() {
  const { ilanEkle } = useApp();
  const [form, setForm] = useState({ nereden: "", nereye: "", yuk: "", ton: "", ucret: "", tarih: "", aracTip: "", aciklama: "", odemeTuru: "pesin", odemeGun: 0 });
  const [tamam, setTamam] = useState(false);
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const gonder = () => {
    if (!form.nereden || !form.nereye || !form.yuk || !form.ucret) return;
    ilanEkle({ ...form, ton: Number(form.ton), ucret: Number(form.ucret), odemeTuru: form.odemeTuru, odemeGun: Number(form.odemeGun) });
    setTamam(true);
    setTimeout(() => { setTamam(false); setForm({ nereden: "", nereye: "", yuk: "", ton: "", ucret: "", tarih: "", aracTip: "", aciklama: "", odemeTuru: "pesin", odemeGun: 0 }); }, 2000);
  };

  const inputStyle = "input";
  const Label = ({ children, zorunlu }) => (
    <label className="label">{children} {zorunlu && <span style={{ color: "var(--turuncu)" }}>*</span>}</label>
  );

  if (tamam) return (
    <div className="scroll-content" style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: 400 }}>
      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: 52, marginBottom: 16 }}>✅</div>
        <div className="display" style={{ fontSize: 28, color: "var(--yesil)" }}>İLAN YAYINDA!</div>
        <div style={{ color: "var(--text3)", marginTop: 8 }}>Teklifler gelmeye başlayacak</div>
      </div>
    </div>
  );

  return (
    <div className="scroll-content">
      <div className="section-title">YENİ İLAN VER</div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>🗺️ Güzergah</div>
        <div className="input-row">
          <div className="input-group">
            <Label zorunlu>Nereden</Label>
            <input className={inputStyle} placeholder="Antalya" value={form.nereden} onChange={e => set("nereden", e.target.value)} />
          </div>
          <div className="input-group">
            <Label zorunlu>Nereye</Label>
            <input className={inputStyle} placeholder="İzmir" value={form.nereye} onChange={e => set("nereye", e.target.value)} />
          </div>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>📦 Yük Bilgisi</div>
        <div className="input-group">
          <Label zorunlu>Yük Türü</Label>
          <input className={inputStyle} placeholder="Kömür, çelik, gıda..." value={form.yuk} onChange={e => set("yuk", e.target.value)} />
        </div>
        <div className="input-row">
          <div className="input-group">
            <Label>Tonaj</Label>
            <input className={inputStyle} type="number" placeholder="22" value={form.ton} onChange={e => set("ton", e.target.value)} />
          </div>
          <div className="input-group">
            <Label zorunlu>Ücret (₺)</Label>
            <input className={inputStyle} type="number" placeholder="8500" value={form.ucret} onChange={e => set("ucret", e.target.value)} />
          </div>
        </div>
        <div className="input-group">
          <Label>Araç Tipi</Label>
          <select className={inputStyle} value={form.aracTip} onChange={e => set("aracTip", e.target.value)} style={{ cursor: "pointer" }}>
            <option value="">Seçin...</option>
            {["TIR / Kapalı Kasa", "Frigorifik TIR", "Flatbed / Lowbed", "Tenteli TIR", "Damperli TIR", "Tanker", "Konteyner"].map(t => <option key={t}>{t}</option>)}
          </select>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>📅 Tarih & Notlar</div>
        <div className="input-group">
          <Label>Yükleme Tarihi</Label>
          <input className={inputStyle} type="date" value={form.tarih} onChange={e => set("tarih", e.target.value)} />
        </div>
        <div className="input-group">
          <Label>Açıklama</Label>
          <textarea className={inputStyle} rows={3} placeholder="Özel şartlar, araç özellikleri..." value={form.aciklama} onChange={e => set("aciklama", e.target.value)} style={{ resize: "vertical", lineHeight: 1.6 }} />
        </div>
      </div>

      {/* Ödeme Planı Seçimi */}
      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 12 }}>💰 Ödeme Planı Seçin</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 8 }}>
          {[
            { tur: "pesin", gun: 0, label: "Peşin", desc: "Hemen tam ödeme", color: "var(--yesil)" },
            { tur: "7-gun", gun: 7, label: "7 Gün", desc: "Teslimden 7 gün sonra", color: "var(--kirmizi)" },
            { tur: "15-gun", gun: 15, label: "15 Gün", desc: "Teslimden 15 gün sonra", color: "var(--sari)" },
            { tur: "30-gun", gun: 30, label: "30 Gün", desc: "Teslimden 30 gün sonra", color: "var(--mavi)" },
          ].map(opt => (
            <button
              key={opt.tur}
              onClick={() => set("odemeTuru", opt.tur)}
              style={{
                padding: "16px 8px",
                borderRadius: "var(--r)",
                border: `2px solid ${form.odemeTuru === opt.tur ? opt.color : "var(--border2)"}`,
                background: form.odemeTuru === opt.tur ? opt.color + "20" : "transparent",
                cursor: "pointer",
                textAlign: "center",
                transition: "var(--tr)"
              }}
            >
              <div style={{ fontWeight: 600, fontSize: 14, color: form.odemeTuru === opt.tur ? opt.color : "var(--text)" }}>{opt.label}</div>
              <div style={{ fontSize: 11, color: "var(--text3)", marginTop: 2 }}>{opt.desc}</div>
            </button>
          ))}
        </div>
      </div>

      {/* Belge yükleme */}
      <div className="card" style={{ marginBottom: 16, textAlign: "center", border: "1px dashed var(--border2)", background: "transparent" }}>
        <div style={{ fontSize: 28, marginBottom: 8 }}>📁</div>
        <div style={{ fontSize: 13, color: "var(--text3)", marginBottom: 10 }}>İrsaliye, makbuz veya sertifika ekle</div>
        <button className="btn btn-secondary" style={{ fontSize: 12 }}>Dosya Seç</button>
      </div>

      <button onClick={gonder} className="btn btn-primary btn-display btn-full" disabled={!form.nereden || !form.nereye || !form.yuk || !form.ucret}>
        📢 İLANI YAYINLA
      </button>
    </div>
  );
}

export function TekliflerSayfasi() {
  const { teklifler, ilanlar, teklifGuncelle } = useApp();
  const getIlan = (id) => ilanlar.find(i => i.id === id);

  return (
    <div className="scroll-content">
      <div className="section-title">GELEN TEKLİFLER ({teklifler.length})</div>
      {teklifler.length === 0
        ? <EmptyState icon="📋" text="Henüz teklif yok" />
        : teklifler.map(t => {
            const ilan = getIlan(t.ilanId);
            return (
              <div key={t.id} className="card" style={{ marginBottom: 10 }}>
                <div style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "8px 12px", marginBottom: 12, fontSize: 12, color: "var(--text3)" }}>
                  📦 {ilan?.yuk} — {ilan?.nereden} → {ilan?.nereye}
                </div>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 8 }}>
                  <div>
                    <div style={{ fontWeight: 600, fontSize: 15 }}>🚛 {t.kamyoncuAd}</div>
                    <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2 }}>🔢 {t.plaka} • ⭐ {t.puan} • 📅 {t.tarih}</div>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <div className="price" style={{ fontSize: 20 }}>₺{t.teklif.toLocaleString()}</div>
                    <Pill durum={t.durum} />
                  </div>
                </div>
                {t.durum === "bekliyor" && (
                  <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginTop: 4 }}>
                    <button onClick={() => teklifGuncelle(t.id, "onaylandı")} className="btn btn-success" style={{ fontSize: 13, padding: "10px" }}>✓ Kabul Et</button>
                    <button onClick={() => teklifGuncelle(t.id, "reddedildi")} className="btn btn-danger" style={{ fontSize: 13, padding: "10px" }}>✕ Reddet</button>
                  </div>
                )}
                {t.durum === "onaylandı" && <div style={{ fontSize: 12, color: "var(--yesil)", marginTop: 6, textAlign: "center" }}>✅ Kamyon ile iletişime geçildi</div>}
                {t.durum === "reddedildi" && <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 6, textAlign: "center" }}>Bu teklif reddedildi</div>}
              </div>
            );
          })
      }
    </div>
  );
}

export function IssizProfilSayfasi() {
  const { oturum, cikisYap, ilanlar } = useApp();
  const benimIlanlarim = ilanlar.filter(i => i.olusturan === (oturum?.ad || oturum?.firmaAdi) || i.olusturan === "Demo Firma");
  return (
    <div className="scroll-content">
      <div className="card" style={{ textAlign: "center", padding: 24, marginBottom: 12 }}>
        <div style={{ fontSize: 48, marginBottom: 10 }}>🏢</div>
        <div className="display" style={{ fontSize: 26 }}>{oturum?.ad || oturum?.firmaAdi || "Demo Firma"}</div>
        <div className="rating" style={{ marginTop: 6 }}>⭐ 4.8 — Güvenilir İş Veren</div>
        <div className="stat-grid" style={{ marginTop: 16 }}>
          <div className="stat-box"><div className="stat-val">{ilanlar.length}</div><div className="stat-lbl">İlan</div></div>
          <div className="stat-box"><div className="stat-val">{ilanlar.filter(i=>i.durum==="alindi").length}</div><div className="stat-lbl">Sefer Sayısı</div></div>
          <div className="stat-box"><div className="stat-val">4.8</div><div className="stat-lbl">Puan</div></div>
        </div>
      </div>
      <div className="section-title">İLANLARIM</div>
      {benimIlanlarim.length === 0 ? (
        <div style={{ textAlign: "center", color: "var(--text3)", marginTop: 16 }}>Henüz ilan yok</div>
      ) : benimIlanlarim.map(i => (
        <div key={i.id} className="card" style={{ marginBottom: 8, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <div style={{ fontWeight: 600 }}>{i.yuk}</div>
            <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2 }}>{i.nereden} → {i.nereye} • {i.istekSayisi} istek</div>
          </div>
          <div className="price" style={{ fontSize: 16 }}>₺{i.ucret.toLocaleString()}</div>
        </div>
      ))}
      <button onClick={cikisYap} className="btn btn-secondary btn-full" style={{ marginTop: 16 }}>Çıkış Yap</button>
    </div>
  );
}
